"""Build the source ledger from retained capture metadata and explicit author coding."""
import csv, hashlib, json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];REPO=ROOT.parents[1]
META={
'P6':('Concentrating Intelligence: Scaling and Market Structure in Artificial Intelligence','Anton Korinek; Jai Vipra','2024-11','NBER Working Paper 33139; November 2024 PDF','original research working paper','PDF pp. 20–23: vertical integration and policy remedies','NBER copyright statement; full reuse permission not established. Private PDF and extraction; narrow extract.','Read the working-paper version, not the later journal version. No 2024 market fact treated as current.','Risks from vertical integration'),
'P1':('AI Sovereignty: Redundant Use of Large Language Models for Public Sector Resilience','Paul F. Langer; Stefan Haag','2026-05-26','DOI 10.1007/s11115-026-01021-4','original research article','PDF pp. 10–16; provider auditing p. 13; fallback p. 15','CC BY 4.0 stated in PDF p. 17. Full text retained privately; only narrow extracts published.','Public-sector conceptual framework. Read beyond abstract; no audited procurement corpus reproduced.','Institutions should assess and audit AI providers'),
'P2':('The AI Resilience Gap: Bringing Artificial Intelligence Inside the Operational Resilience Perimeter','Jonathan Shelby','2026-07-08','arXiv:2607.07359v1','original research preprint','Sections 3–5; framework pp. 6–9','CC BY 4.0 listed on arXiv landing page. Private full text; narrow public extract.','Conceptual resilience framework. No claim that this is legal authority or human peer review.','a fallback that is documented but not resourced is not a control.'),
'P3landing':('The Portability Congestion Paradox: An Economic Model of AI Resilience and Scarce Recovery Capacity','Kwan Hong Tan','2026-09-23','Zenodo 22918523 version 1','author repository landing page','Description; publication and licence fields','Landing page lists CC BY 4.0 and copyright to author. Full PDF was not obtained.','Abstract and metadata only; two PDF attempts timed out. No equation or proof independently verified.','recovery capacity'),
'P5':('Financial Stability in Focus: Artificial intelligence in the financial system','Bank of England','2025-04-09','April 2025 report','official policy analysis','Section 2: Operational risks in relation to AI service providers','No full-redistribution permission established for this capture. Private bytes; narrow public extract.','Financial-system context; statements about risk are not estimates for public benefit systems.','time-critical payments'),
'D1':('Claude Sonnet 4.5 - Amazon Bedrock','Amazon Web Services','unknown','model-card-anthropic-claude-sonnet-4-5.html; retained capture','official product documentation','Model Details; Programmatic Access','AWS terms not independently licensed for full republication. Private original; short extracts only.','Retained bytes say Legacy and EOL 8 April 2027. Older web-reader display differed. Does not establish buyer access or service quality.','Model lifecycle: Legacy|Model EOL date: April 8, 2027|anthropic.claude-sonnet-4-5-20250929-v1:0'),
'D2':('Claude Sonnet 4.5 on Google Cloud','Google Cloud','2026-10-09','page last-updated date; source redirects to Gemini Enterprise Agent Platform','official product documentation','Model ID; Versions; Supported regions','Page states CC BY 4.0 for content unless noted; code samples Apache 2.0. Only short content extracts published.','GA is a launch-stage label. Lower-bound retirement date is not an exact retirement date. No successful call tested.','claude-sonnet-4-5|Launch stage: Generally available|Retirement date not sooner than: September 29, 2026'),
'D3':('Nova Pro - Amazon Bedrock','Amazon Web Services','unknown','model-card-amazon-nova-pro.html; retained capture','official product documentation','Model Details; Programmatic Access','AWS terms not independently licensed for full republication. Private original; short extracts only.','Active label observed in retained bytes. Earliest EOL date is not an exact end date. No successful call tested.','Model lifecycle: Active|amazon.nova-pro-v1:0'),
'D4':('Gemini 2.5 Pro','Google Cloud','2026-10-10','page last-updated date; source redirects to Gemini Enterprise Agent Platform','official product documentation','Model ID; Versions; retirement footnote','Page states CC BY 4.0 for content unless noted; code samples Apache 2.0. Only short content extracts published.','Announced support retirement on cloud platform, not a forecast of physical shutdown or a date for the separate Gemini API.','gemini-2.5-pro|Launch stage: GA|Retirement date†: October 20, 2026|retirement of support in Gemini Enterprise Agent Platform'),
'D5':('Does Amazon Bedrock share input and output data with model providers or use the data to train models?','AWS Support Official','2026-09-23','AWS official answer; update date in official comment','official product explanation','Amazon Bedrock isolates your data','AWS rights not cleared for full republication. Private original; short extract.','Used only to distinguish deployment-account operator from model maker. No independent infrastructure or data-handling audit.','The Amazon Bedrock service team owns and operates these accounts.'),
'D6':('Model lifecycle (Legacy) - Amazon Bedrock','Amazon Web Services','unknown','policy for models launched before 2026-09-07','official product access policy','Legacy definition; scheduled EOL table; Claude Sonnet 4.5 row','AWS rights not cleared for full republication. Private original; short extracts.','Sonnet 4.5 row lists affected commercial regions, including us-east-1. Regional and account state not tested through API. Future policy can change.','New customers can\'t use Legacy models|15 days of inactivity|April 8, 2027'),
'I1':('Anthropic AI via AWS Bedrock: Agentic AI Virtual Collaborator - Claude','SOFTCAT PLC; supplier-authored Digital Marketplace listing','unknown','G-Cloud 15 service 244333610722828','public procurement offer','Service constraints; Scaling; Identity and authentication; Onboarding and offboarding','Government page footer lists OGL with exceptions. Supplier-content full reuse rights not established. Private bytes; narrow extract; contact details not republished.','Offer statements only. Not contract award, certification of capacity, evidence of a particular buyer, or actual use of Sonnet 4.5.','The Standard tier service draws from a shared shared capacity pool'),
'I2':('Artificial Intelligence Playbook for the UK Government (HTML)','Government Digital Service','2025-02-10','official guidance; retrieved HTML','official guidance with public-sector case reports','Appendix: NHS user research finder; NHS.UK reviews','Crown copyright; OGL v3.0 except third-party material. Private full capture; narrow extract.','Case reports show task and load validation questions. This audit does not independently reproduce those projects or apply all legal statements in the guidance.','In early prototyping we attempted to run an in-house LLM.|the quality of the results was not high enough'),
}
def main():
    captures=[json.loads(x) for x in (ROOT/'sources/captures.jsonl').read_text().splitlines()]
    manifest=[];extracts=[]
    for row in captures:
        if row['id'] not in META: continue
        title,author,pub,version,kind,locator,rights,coverage,quotes=META[row['id']]
        entry={**row,'title':title,'author_or_issuer':author,'publication_or_update_date':pub,'date_type':'last update' if row['id'] in ('D2','D4','D5') else 'publication or unknown','version':version,'source_type':kind,'language':'English','claim_location':locator,'rights_and_redistribution':rights,'coverage_limits':coverage,'retention':'Full source and extraction are private, ignored files; public extracts are not full snapshots.'}
        manifest.append(entry)
        txt=' '.join((REPO/row['extracted_path']).read_text().split())
        for j,q in enumerate(quotes.split('|'),1):
            assert q in txt,(row['id'],q)
            extracts.append({'extract_id':row['id']+'-'+str(j),'source_id':row['id'],'locator':locator,'quote':q,'word_count':len(q.split()),'source_sha256':row['sha256']})
    (ROOT/'sources/manifest.json').write_text(json.dumps(manifest,indent=2,ensure_ascii=False)+'\n')
    with (ROOT/'sources/extracts.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(extracts[0]));w.writeheader();w.writerows(extracts)
    print(json.dumps({'retained_sources':len(manifest),'extracts':len(extracts),'failed_captures':sum(x['status']=='failed' for x in captures)}))
if __name__=='__main__':main()

